module uart_tx(
    input clk, // 50MHz clock signal
    input reset, // asynchronous active-high reset
    input tx_start, // start transmitting data
    input [7:0] data_in, // data to be transmitted
    output reg tx); // UART transmit line

reg [12:0] baud_counter;
reg [3:0] bit_counter;
reg shift_register;
reg tx_busy;

always @(posedge clk) begin
    if (reset) begin
        baud_counter <= 0;
        bit_counter <= 0;
        shift_register <= 1'b1;
        tx_busy <= 1'b0;
        tx <= 1'b1; // idle state
    end else if (tx_start && !tx_busy) begin
        baud_counter <= 0;
        bit_counter <= 0;
        shift_register <= {data_in, 1'b0}; // add start bit to data
        tx_busy <= 1'b1;
    end else if (baud_counter == 134) begin // 9600 baud rate
        baud_counter <= 0;
        if (bit_counter < 8) begin // transmit bits
            shift_register <= {shift_register[7:1], 1'b0};
            bit_counter <= bit_counter + 1;
        end else if (tx_busy && !(shift_register & 1)) begin // stop condition is low parity bit
            tx <= ~shift_register[8]; // transmit the data and stop bit
            shift_register <= {data_in, 1'b0}; // load new data to be transmitted
        end else if (tx_busy) begin // send stop bit and wait for start condition again
            tx <= 1'b1; // idle state after transmission
            tx_busy <= 1'b0;
        end else begin // do nothing, just wait for start signal
            shift_register <= {data_in, 1'b0}; // load new data to be transmitted
        end
    end else if (tx_start) begin // ignore additional start conditions while busy
    end else begin // count the baud rate counter when not transmitting
        baud_counter <= baud_counter + 1;
    end
end

always @(posedge clk) begin
    tx <= ~shift_register[8];
end

endmodule

