module fifo(input clk, input reset, 
           input wr_en, input [7:0] din, 
           output reg wr_full, 
           input rd_en, output reg [7:0] dout, 
           output reg empty);

    reg [15:0] data [0:15]; // 16-entry synchronous FIFO
    integer count = 0; // counter to keep track of number of entries in the FIFO
    integer write_ptr = 0; // pointer for writing data into the FIFO
    integer read_ptr = 0; // pointer for reading data from the FIFO

    always @(posedge clk) begin
        if (reset) begin // reset all pointers and counters when reset is asserted
            write_ptr <= 0;
            read_ptr <= 0;
            count <= 0;
            wr_full <= 0;
            empty <= 1;
        end else begin
            if (wr_en && !rd_en) begin // only increment counter and pointer when writing data
                count <= count + 1;
                write_ptr <= write_ptr + 1;
                if (count == 16) wr_full <= 1; // set full flag when the FIFO is filled
            end else if (!wr_en && rd_en) begin // only decrement counter and pointer when reading data
                count <= count - 1;
                read_ptr <= read_ptr + 1;
                empty <= 0;
                wr_full <= 0;
            end

            // check for wraparound in pointers
            if (write_ptr == 16) write_ptr <= 0;
            if (read_ptr == 16) read_ptr <= 0;

            // write data into the FIFO when writing is enabled and the FIFO is not full
            if (wr_en && !rd_en && !wr_full) begin 
                data[write_ptr] <= din;
            end

            // read data from the FIFO when reading is enabled and the FIFO is not empty
            if (!wr_en && rd_en && !empty) begin 
                dout <= data[read_ptr];
            end
        end
    end
endmodule
